// ============================================
// MOCK API (for development)
// ============================================

export const mockApi = {
  async get<T>(endpoint: string, data?: any): Promise<ApiResponse<T>> {
    await simulateDelay(500);
    console.log(`[MOCK API] GET ${endpoint}`, data);
